const html=readFileSync(new URL('../index.html',import.meta.url),'utf8');

function blockById(tag,id){
  const escaped=id.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const matches=[...html.matchAll(new RegExp(`<${tag}[^>]+id=["']${escaped}["'][^>]*>([\\s\\S]*?)<\\/${tag}>`,'g'))];
  assert.equal(matches.length,1,`${id} is installed exactly once`);
  return {source:matches[0][1],index:matches[0].index,end:matches[0].index+matches[0][0].length};
}

function scriptContaining(marker){
  const matches=[...html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/g)].filter((match)=>match[1].includes(marker));
  assert.equal(matches.length,1,`one inline script contains ${marker}`);
  return {source:matches[0][1],index:matches[0].index};
}

